mapper.select:
SELECT * FROM (
SELECT SP.CompCode, SP.StoreCode, SP.ProdCode, SP.LocType, SP.ProdSeq, SP.State, SP.Remark,
       SP.RegistId, SP.RegistName, SP.RegistDate, SP.ChangeId, SP.ChangeName, SP.ChangeDate
FROM shopion.tPrfCompStoreProd SP
INNER JOIN shopion.tPrdProd PH ON SP.ProdCode = PH.ProdCode

    AND SP.StoreCode = #{pStoreCode}
    AND SP.CompCode = #{pCompCode}
    AND SP.ProdCode = #{pProdCode}
    AND PH.SaleYn = #{pSaleYn}

) t_1

    ORDER BY ${sidx} ${sord}
    ORDER BY ProdSeq

LIMIT #{topCnt}, #{countPerPage}

SELECT COUNT(*)
FROM shopion.tPrfCompStoreProd SP
INNER JOIN shopion.tPrdProd PH ON SP.ProdCode = PH.ProdCode

    AND SP.StoreCode = #{pStoreCode}
    AND SP.CompCode = #{pCompCode}
    AND SP.ProdCode = #{pProdCode}
    AND PH.SaleYn = #{pSaleYn}

SELECT *
FROM shopion.tPrfCompStoreProd

    AND StoreCode = #{pStoreCode}
    AND CompCode = #{pCompCode}
    AND ProdCode = #{pProdCode}

LIMIT 0,1

mapper.update:
UPDATE shopion.tPrfCompStoreProd SET
    State = #{state}, Remark = #{remark},
    ChangeId = #{changeId}, ChangeName = #{changeName}, ChangeDate = NOW()
WHERE CompCode = #{compCode}
AND StoreCode = #{storeCode}
AND ProdCode = #{prodCode}

mapper.delete:
